using Microsoft.OpenApi.Models;

builder.Services.AddSwaggerGen(options =>
{
    options.SwaggerDoc("v1", new OpenApiInfo { Title = "Secure API", Version = "v1" });

    options.AddSecurityDefinition("Bearer", new OpenApiSecurityScheme
    {
        In = ParameterLocation.Header,
        Description = "Enter JWT token",
        Name = "Authorization",
        Type = SecuritySchemeType.Http,
        BearerFormat = "JWT",
        Scheme = "Bearer"
    });

    options.AddSecurityRequirement(new OpenApiSecurityRequirement
    {
        {
            new OpenApiSecurityScheme { Reference = new OpenApiReference { Type = ReferenceType.SecurityScheme, Id = "Bearer" } },
            Array.Empty<string>()
        }
    });
});

options.SwaggerDoc("v1", new OpenApiInfo { Title = "API V1", Version = "v1" });
options.SwaggerDoc("v2", new OpenApiInfo { Title = "API V2", Version = "v2" });

options.DocInclusionPredicate((docName, apiDesc) =>
{
    var actionApiVersionModel = apiDesc.ActionDescriptor?.GetApiVersionModel();
    if (actionApiVersionModel == null) return false;
    return actionApiVersionModel.ImplementedApiVersions.Any(v => $"v{v.MajorVersion}" == docName);
});

public class AddResponseHeadersFilter : IOperationFilter
{
    public void Apply(OpenApiOperation operation, OperationFilterContext context)
    {
        operation.Responses["200"].Headers.Add("X-Request-Id", new OpenApiHeader { Description = "Request tracking ID" });
    }
}

// Register
options.OperationFilter<AddResponseHeadersFilter>();

